import{z as d,x as n,o as t,c as i,q as o,j as s,D as a,d as E,s as l,S as A}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"tasklet 与 workqueue","description":"","frontmatter":{"title":"tasklet 与 workqueue","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tasklet-workqueue.md","filePath":"cs/tasklet-workqueue.md","lastUpdated":1791063341000}'),B={name:"cs/tasklet-workqueue.md"};function u(k,e,p,c,_,D){const r=n("Mermaid");return t(),i("div",null,[e[2]||(e[2]=o('<h1 id="tasklet-与-workqueue" tabindex="-1">tasklet 与 workqueue <a class="header-anchor" href="#tasklet-与-workqueue" aria-label="Permalink to &quot;tasklet 与 workqueue&quot;">​</a></h1><div class="epigraph"><p>同一条下半部纪律下，还要再分：仍禁睡眠的串行小函数，以及跑在内核线程里、可以阻塞的工作项。</p><footer>—— 据 Love, Linux Kernel Development；Bovet and Cesati 整理</footer></div><p><a href="/cs/hardirq-softirq">上一课</a>给出硬/软两档上下文，软中断仍不能睡。网卡协议之后若还要分配可睡的内存、要等文件系统，软中断会拖死返回路径。缺口是两种排队对象：<strong>tasklet</strong>（或同类：软中断里串行执行、禁睡眠）与 <strong>workqueue</strong>（内核工作线程上跑、可睡眠）。本课只钉这一分档，不写框架的全部 API。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>软中断类型少、全局 pending 位粗。驱动需要「就这块缓冲、稍后再算」而不占用一种软中断号。tasklet 把函数指针挂进每 CPU 队列，在软中断点串行跑完——仍禁睡眠，但比新注册一种软中断轻。真正要 <code>mutex_lock</code>、要拷用户页，必须换到进程上下文：workqueue 把工作项交给 <code>kworker</code> 一类线程，调度器可见。缺口是这套分流，不是新的设备 IRQ 硬件。</p><p><span class="marginnote">同一 tasklet 在单 CPU 上不重入；能否在多 CPU 上并行，实现有「一次一个」的变体。workqueue 可以并发，提交者必须自己保护共享数据。</span></p><p><span class="marginnote">术语翻译：可睡眠就是「这个函数可能会把自己挂起来等别人——等锁、等内存、等 IO，等待期间让出 CPU」。软中断上下文没有可挂起的调度实体，一旦「睡」了就没人能切走它，整核卡死。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>ISR 或软中断：<code>tasklet_schedule</code> 把后续函数入队；或 <code>queue_work</code> 把项交给工作队列。tasklet 在软中断里执行；work 在线程里执行，可调用<a href="/cs/syscall-path">系统调用路径</a>同款的可睡函数（自己就是内核线程）。禁止在硬 IRQ 里直接睡，这条不变。</p>',9)),(t(),s(A,null,{default:a(()=>[l(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ISR%5B%22%E7%A1%AC%E4%B8%AD%E6%96%AD%22%5D%20--%3E%20TL%5B%22tasklet%3A%20%E7%A6%81%E7%9D%A1%E3%80%81%E8%BD%AF%E4%B8%AD%E6%96%AD%E7%82%B9%22%5D%0A%20%20ISR%20--%3E%20WQ%5B%22workqueue%3A%20%E5%8F%AF%E7%9D%A1%E3%80%81%E7%BA%BF%E7%A8%8B%22%5D%0A%20%20WQ%20--%3E%20SCH%5B%22%E8%BF%9B%E5%85%A5%E8%B0%83%E5%BA%A6%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<p>选择标准：要不要睡、要不要与特定进程的地址空间绑在一起。绑定用户缓冲的工作往往要在发起 <code>read</code> 的那个进程上下文做，那是线程化中断的后话。</p><p><span class="marginnote">直觉类比：tasklet 像「柜台快速业务」——站着办完马上走，中途不许去吃饭（禁睡）；workqueue 像「复杂业务取号」——领了号去排队，轮到你之前调度器可以安排别的活干。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分流让<a href="/cs/scheduling-metrics">调度指标</a>里的延迟可解释：tasklet 仍增加软中断尾延迟；work 的延迟是调度延迟，可能被公平调度器摊薄。上半部与这两类队列之间的描述符仍是共享数据，后课的锁要标明「持锁者能否睡」。</p><p>不要把 workqueue 当成用户进程：它没有用户 trapframe，但有内核栈与调度实体。</p><p><span class="marginnote">常见误区：初学者以为进了 workqueue 就什么都能干。实际上 <code>kworker</code> 没有用户地址空间，拿发起 <code>read</code> 的进程的用户页指针直接拷贝会拷错地方——碰用户缓冲必须回到那个进程的上下文，这正是线程化 IRQ 要解决的。</span></p>',6)),(t(),s(A,null,{default:a(()=>[l(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20JOB%5B%22%E4%B8%80%E6%AE%B5%E5%BB%B6%E5%90%8E%E5%B7%A5%E4%BD%9C%22%5D%20--%3E%20S1%7B%22%E8%A6%81%E6%8B%BF%E4%BA%92%E6%96%A5%E9%94%81%E6%88%96%E4%BF%A1%E5%8F%B7%E9%87%8F%EF%BC%9F%22%7D%0A%20%20S1%20--%3E%7C%22%E8%A6%81%EF%BC%8C%E5%8F%AF%E8%83%BD%E7%9D%A1%22%7C%20WQ%5B%22workqueue%20%2F%20kworker%22%5D%0A%20%20S1%20--%3E%7C%22%E4%B8%8D%E8%A6%81%22%7C%20S2%7B%22%E8%A6%81%E7%AD%89%20IO%20%E6%88%96%E5%8F%AF%E7%9D%A1%E5%88%86%E9%85%8D%EF%BC%9F%22%7D%0A%20%20S2%20--%3E%7C%22%E8%A6%81%22%7C%20WQ%0A%20%20S2%20--%3E%7C%22%E4%B8%8D%E8%A6%81%22%7C%20TL%5B%22tasklet%EF%BC%9A%E8%BD%AF%E4%B8%AD%E6%96%AD%E7%82%B9%E5%BF%AB%E8%BF%9B%E5%BF%AB%E5%87%BA%22%5D%0A%20%20WQ%20--%3E%20CTX%5B%22%E8%BF%9B%E7%A8%8B%E4%B8%8A%E4%B8%8B%E6%96%87%EF%BC%8C%E8%B0%83%E5%BA%A6%E5%99%A8%E5%8F%AF%E8%A7%81%22%5D%0A%20%20TL%20--%3E%20NS%5B%22%E7%A6%81%E7%9D%A1%EF%BC%8C%E4%B8%8D%E5%8D%A0%E8%B0%83%E5%BA%A6%E5%AE%9E%E4%BD%93%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Linux 工作队列的 <code>WQ_HIGHPRI</code>、绑核属性写成运维手册。也不把 tasklet 的弃用时间线当主干：对象是「禁睡回调 vs 可睡线程」，名字可以换。threaded IRQ 是下一课。</p><p>后课默认：可睡工作进线程。若希望整条 IRQ 处理都是可调度、可设优先级的线程，下一课讲中断线程化。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>tasklet：软中断点上的禁睡回调；workqueue：可睡的内核线程工作项。</li><li>硬 IRQ 里仍然不能睡眠。</li><li>把 IRQ 整条做成线程是下一课。</li><li>出处：Love, <em>LKD</em>；Bovet and Cesati。</li></ul>',5))])}const q=d(B,[["render",u]]);export{m as __pageData,q as default};
